int shortest_span(const std::vector<int>& values, long long threshold) {
    std::size_t left = 0, best = values.size() + 1;
    long long sum = 0;
    for (std::size_t right = 0; right < values.size(); ++right) {
        sum += values[right];
        while (sum >= threshold) {
