def shortest_span(values, threshold):
    left = total = 0
    best = len(values) + 1
    for right, value in enumerate(values):
        total += value
        while total >= threshold:
            best = min(best, right - left + 1)
            total -= values[left]
            left += 1
    return best if best <= len(values) else 0

#include <algorithm>
#include <set>
#include <utility>
