def build_layers(n, prerequisites):
    edges = [set() for _ in range(n)]
    degree = [0] * n
    for a, b in set(prerequisites):
        edges[a].add(b)
        degree[b] += 1
    current = [i for i in range(n) if degree[i] == 0]
    rounds = []
    while current:
        rounds.append(sorted(current))
        following = []
        for i in current:
            for j in edges[i]:
                degree[j] -= 1
                if degree[j] == 0:
                    following.append(j)
        current = following
    return rounds if sum(map(len, rounds)) == n else []

#include <algorithm>
